using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace InputFlowStudio;
public interface IPlanDialogs {
 RecordingDecision ChooseRecording(Plan current,string suggested,Func<string,RecordingDestination,string?> error);
 bool ConfirmDelete(string title,string message);
 UnsavedDecision ResolveUnsaved(string action,int count,bool allowDiscard);
 string? Rename(string current,Func<string,string?> error);
}
public sealed class PlanDialogs(Window owner,Func<bool> light) : IPlanDialogs {
 Window Create(string title,StackPanel content){bool ownerAvailable=owner.IsVisible&&owner.WindowState!=WindowState.Minimized;var window=new Window{Title=title,Owner=ownerAvailable?owner:null,Topmost=true,ShowInTaskbar=!ownerAvailable,Width=570,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=ownerAvailable?WindowStartupLocation.CenterOwner:WindowStartupLocation.CenterScreen,FontFamily=new FontFamily("Microsoft YaHei UI"),FontSize=13};window.Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("pack://application:,,,/InputFlowStudio;component/Themes/Studio.xaml")});ThemeService.Apply(window.Resources,light());window.SetResourceReference(Window.BackgroundProperty,"Canvas");window.SetResourceReference(Window.ForegroundProperty,"Ink");content.Margin=new Thickness(24);window.Content=content;window.Loaded+=(_,_)=>window.Activate();return window;}
 static TextBlock Text(string text,int size=13)=>new(){Text=text,FontSize=size,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,16)};
 static Button Button(string text,Action clicked,bool primary=false){var b=new Button{Content=text,MinWidth=88,Margin=new Thickness(8,0,0,0)};if(primary)b.SetResourceReference(FrameworkElement.StyleProperty,"Primary");b.Click+=(_,_)=>clicked();return b;}
 public RecordingDecision ChooseRecording(Plan current,string suggested,Func<string,RecordingDestination,string?> error){
  var panel=new StackPanel();var window=Create("选择录制保存方式",panel);var result=new RecordingDecision(RecordingDestination.Cancel);
  panel.Children.Add(Text("本次录制保存到哪里？",21));panel.Children.Add(Text($"当前方案：{current.Name}（{current.Steps.Count} 步）\n录制结束后才替换原步骤；取消准备、录制失败或没有录到操作时，原方案保持不变。"));
  panel.Children.Add(Text("录制结束后使用以下方案名称（覆盖也会更新名称）："));var name=new TextBox{Text=current.Name};panel.Children.Add(name);panel.Children.Add(Text($"保留原名另存时，新方案自动命名为“{suggested}”。"));var message=Text("");message.SetResourceReference(TextBlock.ForegroundProperty,"RecordInk");panel.Children.Add(message);
  var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,16,0,0)};actions.Children.Add(Button(current.Steps.Count>0?"覆盖当前方案":"录入当前方案",()=>{var issue=error(name.Text,RecordingDestination.Overwrite);if(issue!=null){message.Text=issue;name.Focus();return;}result=new(RecordingDestination.Overwrite,name.Text.Trim());window.DialogResult=true;}));actions.Children.Add(Button("录制为新方案",()=>{string target=string.Equals(name.Text.Trim(),current.Name.Trim(),StringComparison.OrdinalIgnoreCase)?suggested:name.Text.Trim();var issue=error(target,RecordingDestination.NewPlan);if(issue!=null){message.Text=issue;name.Focus();return;}result=new(RecordingDestination.NewPlan,target);window.DialogResult=true;},true));var cancel=Button("取消",()=>window.DialogResult=false);cancel.IsCancel=true;actions.Children.Insert(0,cancel);panel.Children.Add(actions);window.ShowDialog();return result;
 }
 public UnsavedDecision ResolveUnsaved(string action,int count,bool allowDiscard){var panel=new StackPanel();var window=Create("有未保存修改",panel);var result=UnsavedDecision.Cancel;panel.Children.Add(Text("有未保存的方案修改",21));panel.Children.Add(Text($"{count} 个方案存在待保存修改。{action}前是否保存？"));var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,16,0,0)};var cancel=Button("取消",()=>window.DialogResult=false);cancel.IsCancel=true;actions.Children.Add(cancel);if(allowDiscard)actions.Children.Add(Button("放弃修改并退出",()=>{result=UnsavedDecision.Discard;window.DialogResult=true;}));actions.Children.Add(Button("保存并"+action,()=>{result=UnsavedDecision.Save;window.DialogResult=true;},true));panel.Children.Add(actions);window.ShowDialog();return result;}
 public bool ConfirmDelete(string title,string message){var panel=new StackPanel();var window=Create(title,panel);panel.Children.Add(Text(title,21));panel.Children.Add(Text(message));var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,16,0,0)};var cancel=Button("取消",()=>window.DialogResult=false);cancel.IsCancel=true;cancel.IsDefault=true;actions.Children.Add(cancel);actions.Children.Add(Button(title.Contains("还原")?"确认还原":"确认删除",()=>window.DialogResult=true));panel.Children.Add(actions);return window.ShowDialog()==true;}
 public string? Rename(string current,Func<string,string?> error){var panel=new StackPanel();var window=Create("重命名方案",panel);panel.Children.Add(Text("重命名方案",21));var name=new TextBox{Text=current};panel.Children.Add(name);var message=Text("");message.SetResourceReference(TextBlock.ForegroundProperty,"RecordInk");panel.Children.Add(message);var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,16,0,0)};string? result=null;var cancel=Button("取消",()=>window.DialogResult=false);cancel.IsCancel=true;actions.Children.Add(cancel);actions.Children.Add(Button("保存名称",()=>{var issue=error(name.Text);if(issue!=null){message.Text=issue;return;}result=name.Text.Trim();window.DialogResult=true;},true));panel.Children.Add(actions);window.Loaded+=(_,_)=>{name.Focus();name.SelectAll();};window.ShowDialog();return result;}
}

public enum UnsavedDecision { Cancel, Save, Discard }
